/**
 * @file page_manager.c
 * @brief Page manager implementation.
 *
 * Navigation model:
 *  - PUSH:  push current page onto stack, show new page.
 *  - POP:   destroy current page, restore previous from stack.
 *  - REPLACE: destroy current page, show new page (no stack change).
 *  - HOME:  unwind stack, go back to the root (PAGE_HOME).
 *
 * Memory management:
 *  - Each page's root_obj is created on demand and deleted on exit.
 *  - The LVGL screen is reused; only child objects are swapped.
 */

#include "page_manager.h"
#include <lvgl/lvgl.h>
#include <syslog.h>

#define LOG_TAG "page_mgr"

/**********************
 *  STATIC PROTOTYPES
 **********************/
static app_page_desc_t *find_page(app_page_id_t id);
static void show_page(app_page_desc_t *page);
static void hide_current_page(void);

/**********************
 *  IMPLEMENTATION
 **********************/

void page_manager_init(void)
{
    app_context_t *ctx = app_ctx_get();
    ctx->page_count = 0;
    ctx->current_page_idx = -1;
    ctx->stack_top = -1;
    ctx->nav_requested = false;
    memset(ctx->pages, 0, sizeof(ctx->pages));
    syslog(LOG_INFO, "[%s] Page manager initialized\n", LOG_TAG);
}

int page_manager_register(app_page_id_t id, const char *name,
                          const app_page_cbs_t *cbs)
{
    app_context_t *ctx = app_ctx_get();

    if (ctx->page_count >= APP_MAX_PAGES) {
        syslog(LOG_ERR, "[%s] Page registry full!\n", LOG_TAG);
        return -1;
    }

    /* Check for duplicate */
    for (uint32_t i = 0; i < ctx->page_count; i++) {
        if (ctx->pages[i].id == id) {
            syslog(LOG_ERR, "[%s] Page %d already registered\n", LOG_TAG, id);
            return -1;
        }
    }

    app_page_desc_t *desc = &ctx->pages[ctx->page_count];
    desc->id = id;
    desc->name = name;
    desc->cbs = *cbs;
    desc->root_obj = NULL;
    ctx->page_count++;

    syslog(LOG_INFO, "[%s] Registered page: %s (id=%d)\n", LOG_TAG, name, id);
    return 0;
}

static app_page_desc_t *find_page(app_page_id_t id)
{
    app_context_t *ctx = app_ctx_get();
    for (uint32_t i = 0; i < ctx->page_count; i++) {
        if (ctx->pages[i].id == id) {
            return &ctx->pages[i];
        }
    }
    return NULL;
}

static void hide_current_page(void)
{
    app_context_t *ctx = app_ctx_get();

    if (ctx->current_page_idx < 0 ||
        ctx->current_page_idx >= (int32_t)ctx->page_count) {
        return;
    }

    app_page_desc_t *cur = &ctx->pages[ctx->current_page_idx];

    /* Notify page it's leaving */
    if (cur->cbs.on_exit) {
        cur->cbs.on_exit();
    }

    /* Destroy the page UI to free memory */
    if (cur->root_obj) {
        lv_obj_delete(cur->root_obj);
        cur->root_obj = NULL;
    }

    if (cur->cbs.destroy) {
        cur->cbs.destroy();
    }

    syslog(LOG_INFO, "[%s] Hidden page: %s\n", LOG_TAG, cur->name);
}

static void show_page(app_page_desc_t *page)
{
    app_context_t *ctx = app_ctx_get();

    /* Create the page UI on the main screen */
    if (page->cbs.create) {
        page->root_obj = page->cbs.create(ctx->main_screen);
    }

    /* Notify page it's entering */
    if (page->cbs.on_enter) {
        page->cbs.on_enter();
    }

    /* Update current index */
    for (uint32_t i = 0; i < ctx->page_count; i++) {
        if (&ctx->pages[i] == page) {
            ctx->current_page_idx = (int32_t)i;
            break;
        }
    }

    syslog(LOG_INFO, "[%s] Showing page: %s\n", LOG_TAG, page->name);
}

void page_manager_navigate(nav_action_t action, app_page_id_t target)
{
    app_context_t *ctx = app_ctx_get();

    switch (action) {
    case NAV_ACTION_PUSH: {
        /* Push current onto stack, show target */
        if (ctx->stack_top < APP_MAX_PAGES - 1 && ctx->current_page_idx >= 0) {
            ctx->page_stack[++ctx->stack_top] = ctx->current_page_idx;
        }
        hide_current_page();

        app_page_desc_t *page = find_page(target);
        if (page) {
            show_page(page);
        }
        break;
    }

    case NAV_ACTION_POP: {
        /* Pop previous from stack */
        hide_current_page();

        if (ctx->stack_top >= 0) {
            int32_t prev_idx = ctx->page_stack[ctx->stack_top--];
            show_page(&ctx->pages[prev_idx]);
        } else {
            /* Stack empty, go home */
            app_page_desc_t *home = find_page(PAGE_HOME);
            if (home) {
                show_page(home);
            }
        }
        break;
    }

    case NAV_ACTION_REPLACE: {
        /* Destroy current, show target (no stack change) */
        hide_current_page();

        app_page_desc_t *page = find_page(target);
        if (page) {
            show_page(page);
        }
        break;
    }

    case NAV_ACTION_HOME: {
        /* Unwind entire stack */
        hide_current_page();
        ctx->stack_top = -1;

        app_page_desc_t *home = find_page(PAGE_HOME);
        if (home) {
            show_page(home);
        }
        break;
    }

    default:
        break;
    }
}

void page_manager_request_nav(nav_action_t action, app_page_id_t target)
{
    app_context_t *ctx = app_ctx_get();
    ctx->pending_nav.action = action;
    ctx->pending_nav.target_page = target;
    ctx->nav_requested = true;
}

void page_manager_process_nav(void)
{
    app_context_t *ctx = app_ctx_get();

    if (ctx->nav_requested) {
        ctx->nav_requested = false;
        page_manager_navigate(ctx->pending_nav.action,
                              ctx->pending_nav.target_page);
    }
}

app_page_id_t page_manager_get_current(void)
{
    app_context_t *ctx = app_ctx_get();
    if (ctx->current_page_idx >= 0 &&
        ctx->current_page_idx < (int32_t)ctx->page_count) {
        return ctx->pages[ctx->current_page_idx].id;
    }
    return APP_PAGE_ID_INVALID;
}

void page_manager_start(void)
{
    page_manager_navigate(NAV_ACTION_REPLACE, PAGE_HOME);
}
