/* Light theme palette */
static const lv_color_t palette_light[THEME_COLOR_COUNT] = {
    [THEME_COLOR_PRIMARY]      = LV_COLOR_MAKE(0x21, 0x96, 0xF3), /* Blue 500  */
    [THEME_COLOR_SECONDARY]    = LV_COLOR_MAKE(0x4C, 0xAF, 0x50), /* Green 500 */
