/* Dark theme palette */
static const lv_color_t palette_dark[THEME_COLOR_COUNT] = {
    [THEME_COLOR_PRIMARY]      = LV_COLOR_MAKE(0x64, 0xB5, 0xF6), /* Blue 200  */
    [THEME_COLOR_SECONDARY]    = LV_COLOR_MAKE(0x81, 0xC7, 0x84), /* Green 200 */
    [THEME_COLOR_BG]           = LV_COLOR_MAKE(0x12, 0x12, 0x12), /* Dark bg   */
    [THEME_COLOR_SURFACE]      = LV_COLOR_MAKE(0x1E, 0x1E, 0x1E), /* Surface   */
    [THEME_COLOR_TEXT_PRIMARY]  = LV_COLOR_MAKE(0xE0, 0xE0, 0xE0), /* Grey 300  */
    [THEME_COLOR_TEXT_MUTED]   = LV_COLOR_MAKE(0x9E, 0x9E, 0x9E), /* Grey 500  */
    [THEME_COLOR_ACCENT]       = LV_COLOR_MAKE(0xFF, 0xB7, 0x4D), /* Orange 200*/
    [THEME_COLOR_SUCCESS]      = LV_COLOR_MAKE(0x81, 0xC7, 0x84), /* Green 200 */
    [THEME_COLOR_WARNING]      = LV_COLOR_MAKE(0xFF, 0x8A, 0x65), /* DeepOrange200*/
};

static const lv_color_t *current_palette = palette_light;

/* Shared styles */
static lv_style_t style_card;
static lv_style_t style_title;
static lv_style_t style_text;
static bool styles_initialized = false;

/**********************
 *  HELPERS
 **********************/

static const lv_font_t *resolve_font(bool large)
{
    /* Pick best available font at compile time */
    if (large) {
#if LV_FONT_MONTSERRAT_24
        return &lv_font_montserrat_24;
#elif LV_FONT_MONTSERRAT_20
        return &lv_font_montserrat_20;
#elif LV_FONT_MONTSERRAT_18
        return &lv_font_montserrat_18;
#elif LV_FONT_MONTSERRAT_16
        return &lv_font_montserrat_16;
#else
        return LV_FONT_DEFAULT;
#endif
    }

    /* Normal font */
#if LV_FONT_MONTSERRAT_16
    return &lv_font_montserrat_16;
#elif LV_FONT_MONTSERRAT_14
    return &lv_font_montserrat_14;
#else
    return LV_FONT_DEFAULT;
#endif
}

static void init_styles(void)
{
    if (styles_initialized) return;

    /* Card style */
    lv_style_init(&style_card);
    lv_style_set_radius(&style_card, 12);
    lv_style_set_bg_color(&style_card, current_palette[THEME_COLOR_SURFACE]);
    lv_style_set_bg_opa(&style_card, LV_OPA_COVER);
    lv_style_set_shadow_width(&style_card, 16);
    lv_style_set_shadow_color(&style_card,
        lv_color_mix(current_palette[THEME_COLOR_TEXT_MUTED],
                     lv_color_black(), LV_OPA_30));
    lv_style_set_shadow_offset_y(&style_card, 4);
    lv_style_set_pad_all(&style_card, 16);
    lv_style_set_border_width(&style_card, 0);

    /* Title style */
    lv_style_init(&style_title);
    lv_style_set_text_font(&style_title, resolve_font(true));
    lv_style_set_text_color(&style_title,
                            current_palette[THEME_COLOR_TEXT_PRIMARY]);

    /* Body text style */
    lv_style_init(&style_text);
    lv_style_set_text_font(&style_text, resolve_font(false));
    lv_style_set_text_color(&style_text,
                            current_palette[THEME_COLOR_TEXT_PRIMARY]);

    styles_initialized = true;
}

/**********************
 *  GLOBAL FUNCTIONS
 **********************/

void ui_theme_init(void)
{
    app_context_t *ctx = app_ctx_get();
    current_palette = (ctx->state.theme_variant == 1) ?
                      palette_dark : palette_light;
    init_styles();
}

lv_color_t ui_theme_get_color(theme_color_t color)
{
    if (color < THEME_COLOR_COUNT) {
        return current_palette[color];
    }
    return lv_color_black();
}

void ui_theme_apply_card_style(lv_obj_t *obj)
{
    lv_obj_add_style(obj, &style_card, 0);
}

void ui_theme_apply_title_style(lv_obj_t *obj)
{
    lv_obj_add_style(obj, &style_title, 0);
}

void ui_theme_apply_text_style(lv_obj_t *obj)
{
    lv_obj_add_style(obj, &style_text, 0);
}

const lv_font_t *ui_theme_font_large(void)
{
    return resolve_font(true);
}

const lv_font_t *ui_theme_font_normal(void)
{
    return resolve_font(false);
}

const lv_font_t *ui_theme_font_small(void)
{
#if LV_FONT_MONTSERRAT_12
    return &lv_font_montserrat_12;
#else
    return LV_FONT_DEFAULT;
#endif
}

void ui_theme_set_dark(bool dark)
{
    app_context_t *ctx = app_ctx_get();
    ctx->state.theme_variant = dark ? 1 : 0;
    current_palette = dark ? palette_dark : palette_light;

    /* Reset and re-init styles with new palette */
    if (styles_initialized) {
        lv_style_reset(&style_card);
        lv_style_reset(&style_title);
        lv_style_reset(&style_text);
        styles_initialized = false;
    }
    init_styles();
}
