/**
 * @file view_chart.c
 * @brief Chart & widgets dashboard implementation.
 *
 * Layout:
 *  - Header with back button
 *  - Top row: arc gauge + stats labels
 *  - Middle: live line chart
 *  - Bottom: scale / bar indicators
 *
 * Data refresh is driven by a lv_timer created on enter and
 * deleted on exit.
 */

#include "view_chart.h"
#include "../common/ui_theme.h"
#include "../common/ui_components.h"
#include "../logic/state_manager.h"
#include "../page_manager.h"
#include <stdlib.h>

/**********************
 *  STATIC PROTOTYPES
 **********************/
static void chart_timer_cb(lv_timer_t *timer);
static void delete_timer_cb(lv_event_t *e);

/**********************
 *  STATIC VARIABLES
 **********************/
static lv_obj_t *chart_obj;
static lv_chart_series_t *ser1;
static lv_chart_series_t *ser2;
static lv_obj_t *arc_gauge;
static lv_obj_t *value_label;
static lv_obj_t *min_label;
static lv_obj_t *max_label;
static lv_timer_t *data_timer;

static int32_t data_min = 0;
static int32_t data_max = 100;

/**********************
 *  HELPERS
 **********************/

static lv_obj_t *create_stat_card(lv_obj_t *parent, const char *title,
                                   const char *initial_val, lv_color_t color)
{
    lv_obj_t *card = ui_comp_create_card(parent);
    lv_obj_set_flex_align(card, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

    lv_obj_t *ttl = lv_label_create(card);
    lv_label_set_text(ttl, title);
    lv_obj_set_style_text_color(ttl,
                                ui_theme_get_color(THEME_COLOR_TEXT_MUTED), 0);
    lv_obj_set_style_text_font(ttl, ui_theme_font_small(), 0);

    lv_obj_t *val = lv_label_create(card);
    lv_label_set_text(val, initial_val);
    lv_obj_set_style_text_color(val, color, 0);
    lv_obj_set_style_text_font(val, ui_theme_font_large(), 0);

    return val;
}

/**********************
 *  TIMER & ANIMATION
 **********************/

static void chart_timer_cb(lv_timer_t *timer)
{
    LV_UNUSED(timer);

    /* Generate simulated data with smooth random walk */
    static int32_t current = 50;

    int32_t delta = (rand() % 21) - 10; /* -10 to +10 */
    current += delta;
    if (current < 5) current = 5;
    if (current > 95) current = 95;

    /* Update chart series */
    lv_chart_set_next_value(chart_obj, ser1, (lv_coord_t)current);

    int32_t second = 80 - current + (rand() % 11) - 5;
    if (second < 0) second = 0;
    if (second > 100) second = 100;
    lv_chart_set_next_value(chart_obj, ser2, (lv_coord_t)second);

    /* Update arc gauge */
    lv_arc_set_value(arc_gauge, current);

    /* Update labels */
    lv_label_set_text_fmt(value_label, "%"LV_PRId32, current);
    state_manager_set_chart_value(current);

    /* Track min/max */
    if (current < data_min) data_min = current;
    if (current > data_max) data_max = current;
    lv_label_set_text_fmt(min_label, "%"LV_PRId32, data_min);
    lv_label_set_text_fmt(max_label, "%"LV_PRId32, data_max);
}

static void delete_timer_cb(lv_event_t *e)
{
    lv_event_code_t code = lv_event_get_code(e);
    if (code == LV_EVENT_DELETE) {
        lv_timer_t *t = lv_event_get_user_data(e);
        if (t) {
            lv_timer_delete(t);
        }
    }
}

/**********************
 *  PAGE LIFECYCLE
 **********************/

static lv_obj_t *chart_create(lv_obj_t *parent)
{
    data_min = 100;
    data_max = 0;

    /* Main container */
    lv_obj_t *container = lv_obj_create(parent);
    lv_obj_set_size(container, LV_PCT(100), LV_PCT(100));
    lv_obj_set_flex_flow(container, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_all(container, 0, 0);
    lv_obj_set_style_pad_gap(container, 0, 0);
    lv_obj_set_style_bg_color(container,
                              ui_theme_get_color(THEME_COLOR_BG), 0);
    lv_obj_set_style_bg_opa(container, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(container, 0, 0);

    /* Header with back button */
    ui_comp_create_header(container, "Data Dashboard", true);

    /* Scrollable content area */
    lv_obj_t *content = lv_obj_create(container);
    lv_obj_set_size(content, LV_PCT(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(content, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_all(content, 12, 0);
    lv_obj_set_style_pad_gap(content, 12, 0);
    lv_obj_set_style_bg_opa(content, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(content, 0, 0);
    lv_obj_set_flex_grow(content, 1);

    /* ---- Top section: Arc gauge + stats ---- */
    lv_obj_t *top_row = lv_obj_create(content);
    lv_obj_set_size(top_row, LV_PCT(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(top_row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(top_row, LV_FLEX_ALIGN_SPACE_EVENLY,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_bg_opa(top_row, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(top_row, 0, 0);
    lv_obj_set_style_pad_all(top_row, 4, 0);
    lv_obj_remove_flag(top_row, LV_OBJ_FLAG_SCROLLABLE);

    /* Arc gauge card */
    lv_obj_t *gauge_card = ui_comp_create_card(top_row);
    lv_obj_set_size(gauge_card, LV_PCT(45), 140);
    lv_obj_set_flex_align(gauge_card, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

    arc_gauge = lv_arc_create(gauge_card);
    lv_arc_set_range(arc_gauge, 0, 100);
    lv_arc_set_value(arc_gauge, 50);
    lv_arc_set_bg_angles(arc_gauge, 135, 45);
    lv_arc_set_rotation(arc_gauge, 135);
    lv_obj_set_size(arc_gauge, 100, 100);
    lv_obj_remove_flag(arc_gauge, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_set_style_arc_color(arc_gauge,
        ui_theme_get_color(THEME_COLOR_PRIMARY), LV_PART_INDICATOR);

    value_label = lv_label_create(arc_gauge);
    lv_label_set_text(value_label, "50");
    lv_obj_set_style_text_font(value_label, ui_theme_font_large(), 0);
    lv_obj_center(value_label);

    /* Stats column */
    lv_obj_t *stats_col = lv_obj_create(top_row);
    lv_obj_set_size(stats_col, LV_PCT(45), 140);
    lv_obj_set_flex_flow(stats_col, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_gap(stats_col, 8, 0);
    lv_obj_set_style_bg_opa(stats_col, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(stats_col, 0, 0);
    lv_obj_remove_flag(stats_col, LV_OBJ_FLAG_SCROLLABLE);

    min_label = create_stat_card(stats_col, "MIN", "0",
                                 ui_theme_get_color(THEME_COLOR_SUCCESS));
    max_label = create_stat_card(stats_col, "MAX", "0",
                                 ui_theme_get_color(THEME_COLOR_WARNING));

    /* ---- Chart section ---- */
    lv_obj_t *chart_card = ui_comp_create_card(content);
    lv_obj_set_size(chart_card, LV_PCT(100), 200);

    chart_obj = lv_chart_create(chart_card);
    lv_chart_set_type(chart_obj, LV_CHART_TYPE_LINE);
    lv_chart_set_point_count(chart_obj, 60);
    lv_chart_set_div_line_count(chart_obj, 3, 5);
    lv_chart_set_range(chart_obj, LV_CHART_AXIS_PRIMARY_Y, 0, 100);
    lv_obj_set_size(chart_obj, LV_PCT(100), 160);

    ser1 = lv_chart_add_series(chart_obj,
                               ui_theme_get_color(THEME_COLOR_PRIMARY),
                               LV_CHART_AXIS_PRIMARY_Y);
    ser2 = lv_chart_add_series(chart_obj,
                               ui_theme_get_color(THEME_COLOR_ACCENT),
                               LV_CHART_AXIS_PRIMARY_Y);

    /* ---- Data refresh timer ---- */
    data_timer = lv_timer_create(chart_timer_cb,
                                 state_manager_get_chart_period(), NULL);
    lv_timer_set_repeat_count(data_timer, -1);

    /* Delete timer when chart page is deleted */
    lv_obj_add_event_cb(container, delete_timer_cb,
                        LV_EVENT_DELETE, data_timer);

    return container;
}

static void chart_on_enter(void)
{
    data_min = 100;
    data_max = 0;
}

static void chart_destroy(void)
{
    chart_obj = NULL;
    ser1 = NULL;
    ser2 = NULL;
    arc_gauge = NULL;
    value_label = NULL;
    min_label = NULL;
    max_label = NULL;
    data_timer = NULL;
}

/**********************
 *  PUBLIC API
 **********************/

static const app_page_cbs_t chart_cbs = {
    .create   = chart_create,
    .on_enter = chart_on_enter,
    .on_exit  = NULL,
    .destroy  = chart_destroy,
};

const app_page_cbs_t *view_chart_get_cbs(void)
{
    return &chart_cbs;
}
