/**
 * @file app_init.c
 * @brief Application initialization and main entry point.
 *
 * Boot sequence:
 *  1. lv_nuttx_init()  — create display + input device via NuttX drivers
 *  2. Initialize state_manager with defaults
 *  3. Initialize theme
 *  4. Initialize event handler (creates nav timer)
 *  5. Initialize page manager
 *  6. Register all pages
 *  7. Show the home page
 */

#include "app_init.h"
#include "app_context.h"
#include "page_manager.h"
#include "logic/state_manager.h"
#include "logic/event_handler.h"
#include "common/ui_theme.h"
#include "views/view_home.h"
#include "views/view_chart.h"
#include "views/view_settings.h"

#include <lvgl/lvgl.h>
#include <nuttx/config.h>
#include <stdio.h>
#include <syslog.h>

#define LOG_TAG "app_init"

/**********************
 *  IMPLEMENTATION
 **********************/

int app_init(void)
{
    int ret;
    app_context_t *ctx = app_ctx_get();

    syslog(LOG_INFO, "[%s] Starting XFC Smart Panel...\n", LOG_TAG);

    /* ------------------------------------------------
     * Step 1: Initialize NuttX display & input drivers
     * ------------------------------------------------ */
#if LV_USE_NUTTX
    lv_nuttx_dsc_t dsc;
    lv_nuttx_result_t result;

    lv_nuttx_dsc_init(&dsc);

    /* Allow custom fb/input paths via Kconfig if needed */
#ifdef CONFIG_APP_LVGL_APP_FB_PATH
    dsc.fb_path = CONFIG_APP_LVGL_APP_FB_PATH;
#endif
#ifdef CONFIG_APP_LVGL_APP_INPUT_PATH
    dsc.input_path = CONFIG_APP_LVGL_APP_INPUT_PATH;
#endif

    lv_nuttx_init(&dsc, &result);

    ctx->display = result.disp;
    ctx->indev = result.indev;
#else
    /* Non-NuttX: assume lv_init() was called and display exists */
    ctx->display = lv_display_get_default();
    ctx->indev = lv_indev_get_next(NULL);
#endif

    ctx->main_screen = lv_screen_active();

    syslog(LOG_INFO, "[%s] Display driver initialized\n", LOG_TAG);

    /* ------------------------------------------------
     * Step 2: Initialize application state
     * ------------------------------------------------ */
    state_manager_init();
    syslog(LOG_INFO, "[%s] State manager initialized\n", LOG_TAG);

    /* ------------------------------------------------
     * Step 3: Initialize theme
     * ------------------------------------------------ */
    ui_theme_init();
    syslog(LOG_INFO, "[%s] Theme initialized\n", LOG_TAG);

    /* ------------------------------------------------
     * Step 4: Initialize event handler
     * ------------------------------------------------ */
    event_handler_init();
    syslog(LOG_INFO, "[%s] Event handler initialized\n", LOG_TAG);

    /* ------------------------------------------------
     * Step 5: Initialize page manager
     * ------------------------------------------------ */
    page_manager_init();
    syslog(LOG_INFO, "[%s] Page manager initialized\n", LOG_TAG);

    /* ------------------------------------------------
     * Step 6: Register all pages
     * ------------------------------------------------ */
    ret = page_manager_register(PAGE_HOME, "Home", view_home_get_cbs());
    if (ret < 0) goto err;

    ret = page_manager_register(PAGE_CHART, "Chart", view_chart_get_cbs());
    if (ret < 0) goto err;

    ret = page_manager_register(PAGE_SETTINGS, "Settings",
                                view_settings_get_cbs());
    if (ret < 0) goto err;

    syslog(LOG_INFO, "[%s] All pages registered\n", LOG_TAG);

    /* ------------------------------------------------
     * Step 7: Show the home page
     * ------------------------------------------------ */
    page_manager_start();

    syslog(LOG_INFO, "[%s] XFC Smart Panel ready!\n", LOG_TAG);
    return 0;

err:
    syslog(LOG_ERR, "[%s] Initialization failed!\n", LOG_TAG);
    return -1;
}

void app_run_once(void)
{
    lv_timer_handler();
}
