/**
 * @file lvgl_app_main.c
 * @brief NuttX application entry point for XFC Smart Panel.
 *
 * This is the only file that touches the NuttX task infrastructure.
 * It creates the LVGL task, initializes the app, and runs the
 * event loop. All GUI logic lives in the layered modules below.
 */

#include <nuttx/config.h>
#include <stdio.h>
#include <unistd.h>
#include <syslog.h>

#include "app_init.h"

#define LOG_TAG "lvgl_app"

/**
 * NuttX main entry point.
 *
 * Stack size and priority are configured via Kconfig (see Kconfig in this
 * directory). LVGL requires at least 8KB stack; 32KB is recommended for
 * FreeType/ThorVG.
 */
int main(int argc, char *argv[])
{
    int ret;

    syslog(LOG_INFO, "[%s] XFC Smart Panel starting\n", LOG_TAG);

    /* Initialize the entire GUI application */
    ret = app_init();
    if (ret < 0) {
        syslog(LOG_ERR, "[%s] app_init failed: %d\n", LOG_TAG, ret);
        return ret;
    }

    /* Main event loop - LVGL timer handler drives everything */
    while (1) {
        app_run_once();
        usleep(5000); /* ~5ms sleep to yield CPU */
    }

    /* Not reached */
    return 0;
}
